const Hyperblobs = require('hyperblobs')
const b4a = require('b4a')
const crypto = require('crypto')

module.exports = shared_files

// files like the wallpaper or a theme. every device puts its files in its own encrypted blob core,
// the settings only keep where a file is (core key, blob id) and its sha256, so apply stays small
function shared_files ({ store, settings, timeout = 30000 }) {
  const encryption = { key: settings.encryption_key }
  const own = new Hyperblobs(store.get({ name: 'shared-files', encryption }))
  const api = { publish, fetch, close: () => own.core.close() }
  return api

  // id is how the file is known in the synced settings (a hash of the file or of a folder listing)
  async function publish (id, data) {
    const sha256 = hash(data)
    if ((await settings.get_file(id))?.sha256 === sha256) return
    const blob = await own.put(data)
    await settings.add_file(id, { core: b4a.toString(own.core.key, 'hex'), blob, sha256 })
  }

  async function fetch (id) {
    const ref = await settings.get_file(id)
    if (!ref) throw new Error('not shared by the other device yet')
    const core = store.get({ key: b4a.from(ref.core, 'hex'), encryption })
    const data = await new Hyperblobs(core).get(ref.blob, { timeout }).finally(() => core.close())
    if (!data || hash(data) !== ref.sha256) throw new Error('the file did not arrive or is damaged')
    return data
  }
}

function hash (data) { return crypto.createHash('sha256').update(data).digest('hex') }
